;Бармен ПетроPE_SM=-PE_+PL        DW PE0+SM,PE1+SM,PE2+SM,PE3+SM,PE4+SM        DW PE5+SM,PE6+SM,PE7+SM        DW PE8+SM,PE9+SM,PE10+SM,PE11+SM,PE12+SM        DW PE13+SM,PE14+SM        DW PE15+SM,PE16+SM,PE17+SM,PE18+SM		if RUSPE0     DB "Добрые люди сказали, что эта вещь",CR        DB "ваша.",SOBES        DB "Я бы на вашем месте, бабуля, не",CR        DB "верил таким добрым...",END		elsePE0     DB "Kind people said that this thing",CR        DB "belongs to you.",SOBES        DB "If I were you, granny, I wouldn't",CR        DB "believe such kind people...",END				endif		if RUSPE1     DB "Здравствуйте, молодой человек.",CR        DB "Чем это вы занимаетесь?",SOBES        DB "Пивко варю. Людей пою. Да денюжку",CR        DB "собираю.",END		elsePE1     DB "Hello young man.",CR        DB "What are you doing?",SOBES        DB "Crafting the beer, getting people",CR        DB "drunk and earning money.",END				endif		if RUSPE2     DB "Зачем это вы народ честной",CR        DB "спаиваете?",SOBES        DB "А кто вы собственно такая будете,",CR        DB "мадемуазель?",HERO		elsePE2     DB "Why do you getting drunk kind",CR        DB "people?",SOBES        DB "By the way, who are you",CR        DB "mademoiselle?",HERO				endif		if RUS        DB "Я - колдунья. Звать меня Вера.",CR        DB "Пришла помочь беде вашей.",SOBES        DB "Меня зовут Петро. И никого, между",CR        DB "прочим, я не спаиваю. Сами бегут",CR        DB "ко мне, а я их от жажды спасаю.",HERO		else		DB "I am a sorceress Vera.",CR        DB "I came to help you.",SOBES        DB "My name is Petro. By the way, I",CR        DB "am getting drunk people without",CR        DB "the force. I save them from thirst.",HERO		endif		if RUS        DB "Ага, особливо во-о-он того",CR        DB "бедолагу спасли, который стол",CR        DB "лбом вытирает!",SOBES        DB "Дак солнце сегодня шибко жаркое!",CR        DB "Вот голову-то ему и напекло...",HERO		else		DB "Yes, I see. Look at this guy,",CR        DB "who is wiping the table with",CR        DB "his face!",SOBES        DB "Well, its hot today!",CR        DB "He probably has sunstroke...",HERO		endif		if RUS        DB "Ну, будь по-твоему... А ну-ка и я",CR        DB "приобщусь к пивцу свеженькому!",SOBES        DB "Хм, а вам-то зачем?",HERO		else		DB "Well, OK. What if I'll ask",CR        DB "some fresh beer?",SOBES        DB "Hmm... Why do you need it?",HERO		endif		if RUS        DB "В горле пересохло от пыли",CR        DB "дорожной... Мечи, скорее, кружку!",CR        DB "Да похолоднее!",SOBES        DB "Ох, не могу... Последнее вон тем",CR        DB "двум гаврикам ушло...",HERO		else		DB "My throat was dry from the road",CR        DB "dust... Stop talking and bring",CR        DB "my cold beer!",SOBES        DB "Oh, I cann't... I sold the last",CR        DB "beer to thouse guys...",HERO		endif		if RUS        DB "Что же мне от жажды теперь",CR        DB "помирать?",SOBES        DB "Да я нового вмиг наварю! Только в",CR        DB "амбаре у меня шаром покати. Мне б",CR        DB "того, из чего пиво варят найти...",HERO		else        DB "Should I die because of the thirst?",SOBES        DB "I can craft new beer instantly!",CR        DB "But I have no ingredients for it",CR        DB "and I cann't get more...",HERO				endif		if RUSPE3     DB "Петро, а из чего пиво варят? Что",CR        DB "вам нужно?",SOBES        DB "Ага! Так я и скажу! Секрет фирмы.",CR        DB "Ну да вы же колдунья, все секреты",CR        DB "знаете!",SCRPT,24		elsePE3     DB "How you making beer Petro? What do",CR        DB "you need?",SOBES        DB "Ha! This is my business secret!",CR        DB "In the other hand, you are the",CR        DB "sorceress and know everything!",SCRPT,24				endif		if RUSPE4     DB "Вот хмель. Угадала?",SOBES        DB "Смотри-ка!.. А где остальное?",HERO        DB "Скоро принесу.",DIALOG,12		elsePE4     DB "Here is the hop. Right?",SOBES        DB "Wow!.. And the rest?",HERO        DB "You'll get soon.",DIALOG,12				endif		if RUSPE5     DB "Вот вам мед...",SOBES        DB "В точку! Но чего-то не хватает...",CR        DB DIALOG,12		elsePE5     DB "Here is some honey...",SOBES        DB "Exactly! But I am still missing",CR		DB "something...",CR        DB DIALOG,12				endif		if RUSPE6     DB "Возьмите пшеницу.",SOBES        DB "Колосья? Спасибо, веник у меня",CR        DB "уже есть...",DIALOG,12		elsePE6     DB "Take the wheat.",SOBES        DB "Ears of corn? Thank you, I",CR        DB "already have a broom...",DIALOG,12				endif		if RUSPE7     DB "Вот вам зерна пшеницы.",SOBES        DB "Вот это другое дело! Еще немного",CR        DB "и все...",DIALOG,12		elsePE7     DB "Here is the wheat grains.",SOBES        DB "Cool! I got almost everything",CR        DB "what i need...",DIALOG,12				endif		if RUSPE8     DB "Возьмите последний ингредиент.",CR        DB "Когда будет готово пиво?",SOBES        DB "Приходите через полчаса.",SCRPT,26		elsePE8     DB "Take the last ingredient.",CR        DB "When I can get my beer?",SOBES        DB "I need 30 minutes.",SCRPT,26				endif		if RUSPE9     DB "Пиво еще не готово?",SOBES        DB "Наберитесь терпения, бабуля!",END		elsePE9     DB "My beer is ready?",SOBES        DB "Take your time granny!",END		endif		if RUSPE10    DB "Ну где же пиво?",SOBES        DB "Забирайте!",SCRPT,27		elsePE10    DB "Where is my beer?",SOBES        DB "Take it!",SCRPT,27				endif		if RUSPE11    DB "Петро, вы не отдадите мне пустой",CR        DB "флакон? Он мне еще нужен.",SOBES        DB "Конечно, берите.",SCRPT,28		elsePE11    DB "Can you give me the empty bottle?",CR        DB "I need it.",SOBES        DB "Sure. Here you are.",SCRPT,28				endif		if RUSPE12    DB "Как дела, Петро?",SOBES        DB "Нормально.",END		elsePE12    DB "How are you Petro?",SOBES        DB "I am fine.",END				endif		if RUSPE13    DB "Вам случайно мед не нужен?",SOBES        DB "Спасибо, но у меня пока есть.",SCRPT,0		elsePE13    DB "Do you need some honey?",SOBES        DB "Thanks, I have it.",SCRPT,0				endif		if RUSPE14    DB "Послушай, Петро, у тебя случайно",CR        DB "огонька не найдется?",SOBES        DB "Найду, но прежде помоги мне найти",CR        DB "кастрюлю. Придворные Зловета",CR        DB "опять ее у меня утащили.",HERO		elsePE14    DB "Listen Petro, do you have some",CR        DB "light?",SOBES        DB "I will find, but help me to find",CR        DB "the saucepan first. It was stolen",CR        DB "again by Evilon's henchmen .",HERO				endif		if RUS        DB "Хорошо, я помогу тебе!",SCRPT,31		else        DB "We have a deal!",SCRPT,31				endif		if RUSPE15    DB "Что-то я не могу найти кастрюлю.",CR        DB "Может, ты мне просто так дашь",CR        DB "огонька?",SOBES        DB "Просто так ничего не бывает.",END		elsePE15    DB "I cannot find your saucepan.",CR        DB "Can you give me the light for",CR        DB "free?",SOBES        DB "You can get nothing for free.",END				endif;           123456789-123456789-123456789-123		if RUSPE16    DB "Вот твоя кастрюля, Петро!",SOBES        DB "Кастрюля? Какая кастрюля? Ах,",CR        DB "эта... Возьми спички, ты вроде их",CR        DB "просила.",SCRPT,32		elsePE16    DB "Here is you saucepan Petro!",SOBES        DB "The saucepan? Which saucepan? Oh,",CR        DB "this one... Take the matches which",CR        DB "you are asked for.",SCRPT,32				endif		if RUSPE17    DB "Петро, скажите...",SOBES        DB "У меня ничего нет, все кончилось.",END		elsePE17    DB "Can you...",SOBES        DB "I have nothing.",END				endif		if RUSPE18    DB "Вроде это тебе.",SOBES        DB "А ну кыш отсюдова!",END		elsePE18    DB "I think that it yours.",SOBES        DB "Go away!",END				endifPEND